    <footer class="paper-foot">
      <span class="dot"></span>
    </footer>
  </article>

  <script>
    (function(){
      var host = document.getElementById('paperBody');
      if(!host) return;
      var raw = '';
      try{
        var blocks = document.querySelectorAll('story');
        if(blocks.length){
          raw = blocks[blocks.length - 1].innerHTML;
        }
      }catch(e){}
      if(!raw){
        var all = document.body.innerHTML || '';
        var m = all.match(/<story>([\s\S]*?)<\/story>/);
        if(m){ raw = m[1]; }
      }
      raw = raw.replace(/<StatusPlaceHolderImpl\s*\/?>/g, '').trim();
      if(!raw) return;

      var paras = raw.split(/\n{2,}/).map(function(s){ return s.trim(); }).filter(Boolean);
      if(!paras.length){ paras = [raw]; }
      var html = '';
      for(var i = 0; i < paras.length; i++){
        var p = paras[i]
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
          .replace(/\*(.+?)\*/g, '<em>$1</em>')
          .replace(/^---+$/gm, '<hr>')
          .replace(/\n/g, '<br>');
        html += '<p>' + p + '</p>';
      }
      host.innerHTML = html;
    })();
